    def myPow(self, x: float, n: int) -> float:
        if n == 0:
            return 1

        # negative
        if n < 0:
            x = 1/x
            n = -n

        result = 1.0
        current_power = x
        while n > 0:
            if n%2 == 1:
                result *= current_power

            current_power *= current_power
            n = n // 2

        return result

